-- Exact original aMw -> bbx.a -> fwt diets. YI is key presence, not raw Boolean value.
CREATE TABLE native_pet_feeding_food_policy (
 model_id integer NOT NULL REFERENCES native_pet_models(model_id),
 item_ref integer NOT NULL CHECK(item_ref>0),
 effect_kind text NOT NULL CHECK(effect_kind IN ('xp','heal')),
 xp_per_item integer NOT NULL CHECK(xp_per_item>=0),
 health_per_item integer NOT NULL CHECK(health_per_item>=0),
 native_xp_flag boolean,
 action_id integer CHECK(action_id>0),
 source_sha256 text NOT NULL,
 PRIMARY KEY(model_id,item_ref),
 CHECK((effect_kind='xp' AND health_per_item=0 AND native_xp_flag IS NOT NULL)
    OR (effect_kind='heal' AND health_per_item>0 AND xp_per_item=0 AND action_id IS NULL AND native_xp_flag IS NULL))
);

ALTER TABLE pet_feeding_receipts DROP CONSTRAINT pet_feeding_receipts_xp_delta_check;
ALTER TABLE pet_feeding_receipts ADD CONSTRAINT pet_feeding_receipts_xp_delta_check CHECK(xp_delta>=0);
ALTER TABLE pet_feeding_receipts ADD COLUMN health_delta integer NOT NULL DEFAULT 0 CHECK(health_delta>=0);
ALTER TABLE pet_feeding_receipts ADD COLUMN effect_kind text NOT NULL DEFAULT 'xp' CHECK(effect_kind IN ('xp','heal'));
ALTER TABLE pet_feeding_receipts ADD CONSTRAINT pet_feeding_receipts_effect_delta_check
 CHECK((effect_kind='xp' AND xp_delta>0 AND health_delta=0) OR (effect_kind='heal' AND health_delta>0 AND xp_delta=0));
